//! The weather service: the weather fixture's operations, generated by
//! build.rs from the `weather-model` package, implemented over a
//! [`CityStore`]. The service type holds dependencies, never data, so any
//! number of instances (Lambda, ECS tasks) serve the same cities.
//!
//! Laid out the way a crucible service is:
//!
//! ```text
//! src/
//!   lib.rs       include_service!() declares the weather API module
//!   operations/  one file per operation, a folder per resource
//!   middlewares/ one file per middleware: middlewares::FailTimes
//! ```

use std::sync::Arc;

use crucible_server_runtime_rust::ExceptionTranslator;
use crucible_server_runtime_rust::middlewares::ServiceLog;
use crucible_server_runtime_rust::{Crucible, InvokeProtocol, JsonProtocol};

// The model's types, errors and operation traits, generated by build.rs.
crucible_server_runtime_rust::include_service!();
mod middlewares;
mod operations;
mod store;

pub use operations::Weather;
pub use store::{CityStore, MemoryCities, NameTaken, NewCity, StoredPhoto};

use weather::ConflictError;

/// The service over `cities`: every operation on one `Weather`, the default
/// chain plus the test hook, and the store's errors translated.
pub fn service(cities: Arc<dyn CityStore>) -> Crucible {
    builder(cities).build().expect("the weather service builds")
}

/// [`service`] before `build`, for a caller that adds layers.
pub fn builder(cities: Arc<dyn CityStore>) -> crucible_server_runtime_rust::Builder {
    let translator = ExceptionTranslator::new().translate(|taken: &NameTaken| {
        ConflictError {
            message: taken.to_string(),
        }
        .into()
    });
    Crucible::builder(weather::operations(Arc::new(Weather::new(cities))))
        .middleware(ServiceLog::errors_only())
        .exception_translator(translator)
        .operation_middleware(middlewares::FailTimes::default())
        .protocol(JsonProtocol)
        .protocol(InvokeProtocol)
}
